  1	function fib(n : nat) : nat
  2	{
  3	  if (n==0) then 1 else
  4	  if (n==1) then 1 else fib(n-1)+fib(n-2)
  5	}
  6	
  7	method Fib(n : nat) returns (r:nat)
  8	  ensures r == fib(n)
  9	{
 10	
 11	  if (n == 0) {
 12	    return 1;
 13	  }
 14	
 15	  var next:= 2;
 16	  r:=1;
 17	  var i := 1;
 18	
 19	  while (i < n)
 20	    invariant next == fib(i+1)
 21	    invariant r == fib(i)
 22	    invariant 1 <= i <= n
 23	  {
 24	    var tmp := next;
 25	    next := next + r;
 26	    r := tmp;
 27	    i := i + 1;
 28	  }
 29	  assert r == fib(n);
 30	  return r;
 31	}
