 34	datatype List<T> = Nil | Cons(head: T, tail: List<T>)
 35	
 36	function add(l : List<int>) : int {
 37	  match l
 38	  case Nil => 0
 39	  case Cons(x,xs) => x + add(xs)
 40	}
 41	
 42	method addImp(l : List<int>) returns (r: int)
 43	  ensures r == add(l)
 44	{
 45	  r := 0;
 46	  var ll := l;
 47	  while (ll != Nil)
 48	    decreases ll
 49	    invariant r==add(l) - add(ll)
 50	  {
 51	    r := r + ll.head;
 52	    ll := ll.tail;
 53	
 54	  }
 55	
 56	  assert r == add(l);
 57	}
