 60	method maxArray(arr : array<int>) returns (max: int)
 61	  requires arr.Length > 0
 62	  ensures forall i: int :: 0 <= i < arr.Length ==> arr[i] <= max
 63	  ensures exists x::0 <= x < arr.Length && arr[x] == max
 64	{
 65	  max := arr[0];
 66	  var index := 1;
 67	  while(index < arr.Length)
 68	    invariant 0 <= index <= arr.Length
 69	    invariant forall i: int :: 0 <= i < index ==> arr[i] <= max
 70	    invariant exists x::0 <= x < arr.Length && arr[x] == max
 71	
 72	  {
 73	    if (arr[index] > max) {
 74	      max := arr[index];
 75	    }
 76	    index := index + 1;
 77	  }
 78	}
 79	
 80	// 5.
 81	method maxArrayReverse(arr : array<int>) returns (max: int)
 82	  ensures forall i: int :: 0 <= i < arr.Length ==> arr[i] <= max
 83	  ensures exists x::0 <= x < arr.Length && arr[x] == max
 84	{
 85	  var ind := arr.Length - 1;
 86	  max := arr[ind];
 87	
 88	  while ind > 0
 89	    invariant 0 <= ind <= arr.Length
 90	    invariant forall i: int :: ind <= i < arr.Length ==> arr[i] <= max
 91	    invariant exists x::0 <= x < arr.Length && arr[x] == max
 92	  {
 93	
 94	    if (arr[ind - 1] > max) {
 95	      max := arr[ind - 1];
 96	    }
 97	    ind := ind - 1;
 98	  }
 99	}
