102	function sum(n: nat) : nat
103	{
104	  if (n == 0) then 0 else n + sum(n-1)
105	}
106	
107	method sumBackwards(n: nat) returns (r: nat)
108	  ensures r == sum(n)
109	{
110	  var i := n;
111	  r := 0;
112	
113	  while i > 0
114	    invariant 0 <= i <= n
115	    invariant r == sum(n) - sum(i)
116	
117	  {
118	    r := r + i;
119	    i := i - 1;
120	  }
121	}

